  if(homeTimer){const tick=()=>{const seconds=300-(Math.floor(Date.now()/1000)%300);homeTimer.textContent=`Następne notowanie za ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;};tick();setInterval(tick,1000);}
