    if(Array.isArray(history)&&typeof allData!=='undefined'&&history.length){allData.splice(0,allData.length,...history.map(item=>({date:item.date,value:Number(item.value)})));document.querySelector('.chart-foot span:last-child').textContent=history.length>1?'Aktualne notowania':'Dostępny jest bieżący kurs';drawChart();homeHistory=history;renderHomeChart(history);}
